    if (!has) return r
    const fw = [...((r.metadata as any)?.detectedFrameworks ?? []), "Targeted/ID-Styling"]
    return { ...r, metadata: { ...(r.metadata ?? {}), detectedFrameworks: [...new Set(fw)] } }
